/// <summary>
/// Charge through invoice posting class
/// </summary>
public class METCBCTInvoicePosting
{
   
}

Method.Source:
/// <summary>
///  Create a new instance of  METCBCTInvoicePosting class
/// </summary>
/// <returns>
/// A new instance of METCBCTInvoicePosting class
/// </returns>
public static METCBCTInvoicePosting construct()
{
    return new METCBCTInvoicePosting();
}

    /// <summary>
    /// Post invoice for the charge through invoice
    /// </summary>
    /// <param name="_cbCtInvoiceHeaderTableList"><c>RecordSortedList</c>
    /// </param>
    /// <returns>
    /// A boolean value 
    /// </returns>
    public boolean postInvoice(RecordSortedList  _cbCtInvoiceHeaderTableList)
    {
        boolean                         ret = true;
        METCBCTInvoiceHeaderTable       cbCTInvoiceHeaderTable;
        boolean                         haveMoreRecords;

        haveMoreRecords = _cbCtInvoiceHeaderTableList.first(cbCTInvoiceHeaderTable);

        while (haveMoreRecords)
        {
            ttsbegin;
            this.doRun(cbCTInvoiceHeaderTable);
            ttscommit;
        }

        return ret;
    }

    /// <summary>
    /// Perform posting tasks 
    /// </summary>
    /// <param name="_cbCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
    public void doRun(METCBCTInvoiceHeaderTable  _cbCTInvoiceHeaderTable)
    {
        METCBCTInvoiceHeaderTable       cbCTInvoiceHeaderTable = _cbCTInvoiceHeaderTable;
        SalesId                         salesId;
       

        //Create sales order 
        salesId = this.createSalesOrder(_cbCTInvoiceHeaderTable);
        //Create pending vendor invoice 
        this.createPendingVendorInvoice(_cbCTInvoiceHeaderTable);

        ttsbegin;
        _cbCTInvoiceHeaderTable.selectForUpdate(true);
        _cbCTInvoiceHeaderTable.RefSalesId = salesId;
        _cbCTInvoiceHeaderTable.Status = METCBCTInvoiceStatus::Processed;
        _cbCTInvoiceHeaderTable.update();
        ttscommit;
        info(strFmt("@MET:ChargethroughInvoicePosted",cbCTInvoiceHeaderTable.Number));

    }

/// <summary>
/// Entry point of the class
/// </summary>
/// <param name="args"><c>Args</c></param>
static void main(Args args)
{
    METCBCTInvoicePosting       process = METCBCTInvoicePosting::construct();
    FormDataSource              formDataSource;
    METCBCTInvoiceHeaderTable   invoiceHeaderTable;

    if (args && args.dataset() == tableNum(METCBCTInvoiceHeaderTable))
    {
        invoiceHeaderTable = args.record();
        if (invoiceHeaderTable.Status == METCBCTInvoiceStatus::Processed)
        {
            throw Error("@MET:ChargethroughInvoiceIsAlreadyProcessed");
        }
        if (invoiceHeaderTable.DocumentDate == dateNull())
        {
            throw Error("@MET:DocumentDateMustBeDefined");
        }
        process.doRun(args.record());
    }
    else
    {
        throw error(strfmt("@SYS19306","@MET:Posting"));
    }

    if (FormDataUtil::isFormDataSource(args.record()))
    {
        formDataSource = FormDataUtil::getFormDataSource(args.record());
        formDataSource.research(true);
    }
}

    /// <summary>
    /// Create sales order for the invoice 
    /// </summary>
    /// <param name="_cbCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
    /// <returns>
    /// SalesID of the sales order
    /// </returns>
    private SalesId createSalesOrder(METCBCTInvoiceHeaderTable  _cbCTInvoiceHeaderTable)
    {
        NumberSeq   numberSeq = NumberSeq::newGetNum(SalesParameters::numRefSalesId());
        SalesTable  salesTable;
        CustTable   custTable = CustTable::find(_cbCTInvoiceHeaderTable.CustomerAccount);
        SalesId     salesId;
        SalesLine   salesLine;

        ttsbegin;
        salesTable.clear();
        salesTable.initValue();
        salesTable.SalesType =  SalesType::Sales;
        salesTable.CustAccount = _cbCTInvoiceHeaderTable.CustomerAccount;
        salesTable.initFromCustTable();
        salesTable.SalesId = numberSeq.num();
        salesTable.TaxGroup = custTable.TaxGroup;
        salesTable.insert();
        if (salesTable.RecId)
        {
            salesId = salesTable.SalesId;
        }

        METCBCTInvoiceLine      cbCTInvoiceLine;

        while select cbCTInvoiceLine 
            where cbCTInvoiceLine.HeaderNumber == _cbCTInvoiceHeaderTable.Number 
            && cbCTInvoiceLine.VendCustType == METCBCTVendCust::Cust
        {
            //creating sales order line
            salesLine.clear();
            salesLine.SalesId = salesId;
            salesLine.initFromSalesTable(salesTable);
            salesLine.ItemId = cbCTInvoiceLine.ItemId;
            salesLine.initLineFromItemOrCategory();

            InventDim inventDim;
            inventDim.InventSiteId = cbCTInvoiceLine.InventSiteId;
            inventDim.InventLocationId = cbCTInvoiceLine.InventLocationId;

            inventDim = InventDim::findOrCreate(inventDim);
            salesLine.InventDimId = inventDim.inventDimId;
            salesLine.SalesQty = cbCTInvoiceLine.Qty;
            salesLine.QtyOrdered = salesLine.calcQtyOrdered();
            salesLine.LineDisc = 0;
           
            salesLine.TaxGroup = cbCTInvoiceLine.TaxGroup;
            salesLine.TaxItemGroup = cbCTInvoiceLine.TaxItemGroup;
          
            salesLine.createLine(true, // Validate
                                true,  // initFromSalesTable
                                true,  // initFromInventTable
                                true,  // calcInventQty
                                true,  // searchMarkup
                                false  // searchPrice
                                );

            salesLine.SalesPrice = cbCTInvoiceLine.Amount;
            salesLine.LineAmount = salesLine.SalesQty *  salesLine.SalesPrice;
            salesLine.DefaultDimension = cbCTInvoiceLine.FinancialDimension;
            salesLine.update();

            this.createMarkUpTransForSalesLine(salesLine,cbCTInvoiceLine);
            /*
            //Copy auto charges from charge through invoice line to sales order line
            MarkupTrans       markUpTransChargeThrough, markUpTransSalesLine;
            LineNum           markUpTransSalesLineLineNum = MarkupTrans::lastLineNum(salesLine.TableId, salesLine.RecId);
            RecordInsertList  markUpTransSalesLineRecordInsertList;

            markUpTransSalesLineRecordInsertList = new RecordInsertList(tableNum(MarkupTrans));

            while select markUpTransChargeThrough
                where markUpTransChargeThrough.TransTableId == cbCTInvoiceLine.TableId
                && markUpTransChargeThrough.TransRecId == cbCTInvoiceLine.RecId
            {
                markUpTransSalesLineLineNum++;
                markUpTransSalesLine.clear();
                markUpTransSalesLine.data(markUpTransChargeThrough);
                markUpTransSalesLine.TransTableId   = salesLine.TableId;
                markUpTransSalesLine.TransRecId     = salesLine.RecId;
                markUpTransSalesLine.LineNum        = markUpTransSalesLineLineNum;
                markUpTransSalesLineRecordInsertList.add(markUpTransSalesLine);
            }
            markUpTransSalesLineRecordInsertList.insertDatabase();*/

        }
        ttscommit;
        return salesId;
    }

    /// <summary>
    /// Copy auto charges from charge through invoice line to sales order line
    /// </summary>
    /// <param name="_salesLine"><c>SalesLine</c></param>
    /// /// <param name="_cbctInvoiceLine"><c>METCBCTInvoiceLine</c></param>
    public void createMarkUpTransForSalesLine(SalesLine     _salesLine, METCBCTInvoiceLine  _cbctInvoiceLine)
    {
        MarkupTrans       markUpTransChargeThrough, markUpTransSalesLine;
        LineNum           markUpTransSalesLineLineNum = MarkupTrans::lastLineNum(_salesLine.TableId, _salesLine.RecId);
        RecordInsertList  markUpTransSalesLineRecordInsertList;

        markUpTransSalesLineRecordInsertList = new RecordInsertList(tableNum(MarkupTrans));

        while select markUpTransChargeThrough
                where markUpTransChargeThrough.TransTableId == _cbctInvoiceLine.TableId
                && markUpTransChargeThrough.TransRecId == _cbctInvoiceLine.RecId
        {
            markUpTransSalesLineLineNum++;
            markUpTransSalesLine.clear();
            markUpTransSalesLine.data(markUpTransChargeThrough);
            markUpTransSalesLine.TransTableId   = _salesLine.TableId;
            markUpTransSalesLine.TransRecId     = _salesLine.RecId;
            markUpTransSalesLine.LineNum        = markUpTransSalesLineLineNum;
            markUpTransSalesLineRecordInsertList.add(markUpTransSalesLine);
        }
        markUpTransSalesLineRecordInsertList.insertDatabase();
    }

    /// <summary>
    /// create pending vendor invoice 
    /// </summary>
    /// <param name="_cbCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
    private void createPendingVendorInvoice(METCBCTInvoiceHeaderTable  _cbCTInvoiceHeaderTable)
    {
        VendInvoiceInfoTable    vendInvoiceInfoTable;
        VendTable               vendTable = VendTable::find(_cbCTInvoiceHeaderTable.VendorAccount);

        vendInvoiceInfoTable.TableRefId             = formletterParmData::getNewTableRefId();
        vendInvoiceInfoTable.DocumentDate           = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
        vendInvoiceInfoTable.CurrencyCode           = _cbCTInvoiceHeaderTable.CurrencyCode;
        vendInvoiceInfoTable.TransDate              = _cbCTInvoiceHeaderTable.TransactionDate;
        vendInvoiceInfoTable.Num                    = _cbCTInvoiceHeaderTable.TaxInvoiceNum;
        vendInvoiceInfoTable.OrderAccount           = vendTable.AccountNum;
        vendInvoiceInfoTable.InvoiceAccount         = vendTable.AccountNum;
        vendInvoiceInfoTable.ParmJobStatus          = ParmJobStatus::Waiting;
        vendInvoiceInfoTable.VendInvoiceSaveStatus  = VendInvoiceSaveStatus::Pending;
        vendInvoiceInfoTable.InclTax                = NoYes::Yes; //TODO: check the value

        vendInvoiceInfoTable.defaultRow();
        if (vendInvoiceInfoTable.validateWrite())
        {
            vendInvoiceInfoTable.insert();
            info(strFmt("@MET:VendorInvoiceIsCreated",vendInvoiceInfoTable.Num));
        }
        else
        {
            error("@Proj:VendorInvoiceNotCreated");
        }

        VendInvoiceInfoSubTable::createFromVendInvoiceInfoTable(vendInvoiceInfoTable);

        METCBCTInvoiceLine      cbCTInvoiceLine;
        VendInvoiceInfoLine     vendInvoiceLine;
        RecordInsertList        vendInvoiceLineInsertList;

        vendInvoiceLineInsertList = new RecordInsertList(tableNum(VendInvoiceInfoLine));

        while select cbCTInvoiceLine
            where cbCTInvoiceLine.HeaderNumber == _cbCTInvoiceHeaderTable.Number
            && cbCTInvoiceLine.VendCustType == METCBCTVendCust::Vend
        {
            vendInvoiceLine.clear();
            vendInvoiceLine.initValue();
            vendInvoiceLine.TableRefId          = vendInvoiceInfoTable.TableRefid;
            vendInvoiceLine.Description         = cbCTInvoiceLine.Description;
            vendInvoiceLine.OrderAccount        = vendTable.AccountNum;
            vendInvoiceLine.InventDimId         = InventDim::findOrCreateBlank().inventDimId;
            vendInvoiceLine.currencyCode        = vendInvoiceInfoTable.CurrencyCode;
            vendInvoiceLine.ItemId              = cbCTInvoiceLine.ItemId;
            vendInvoiceLine.ReceiveNow          = cbCTInvoiceLine.Qty;
            vendInvoiceLine.PriceUnit           = cbCTInvoiceLine.Amount;
            vendInvoiceLine.LineAmount          = cbCTInvoiceLine.Qty * cbCTInvoiceLine.Amount;
            vendInvoiceLine.TaxGroup            = cbCTInvoiceLine.TaxGroup;
            vendInvoiceLine.TaxItemGroup        = cbCTInvoiceLine.TaxItemGroup;
            vendInvoiceLine.DefaultDimension    = cbCTInvoiceLine.FinancialDimension;
            vendInvoiceLineInsertList.add(vendInvoiceLine);
        }
        vendInvoiceLineInsertList.insertDatabase();

        //Update auto charges item GST tax code 
        MarkupTrans     markUpTrans;
        vendInvoiceLine.clear(); //Clear the buffer 

        while select markUpTrans
            where ! markUpTrans.TaxItemGroup 
        join vendInvoiceLine 
            where  markUpTrans.TransTableId == vendInvoiceLine.TableId
            && markUpTrans.TransRecId == vendInvoiceLine.RecId
            && vendInvoiceLine.TableRefId == vendInvoiceInfoTable.TableRefid
        {
            if (markUpTrans.RecId && vendInvoiceLine.TaxItemGroup)
            {
                ttsbegin;
                markUpTrans.selectForUpdate(true);
                markUpTrans.TaxItemGroup = vendInvoiceLine.TaxItemGroup;
                markUpTrans.update();
                ttscommit;
            }
        }

    }
